// ── js/engine/core.js ──
// ╔══════════════════════════════════════════════════════════════════╗
// ║  ENGINE-CORE.JS — Shared state, storage, and utility functions      ║
// ║                                                                    ║
// ║  Loaded FIRST among the engine modules — everything else depends   ║
// ║  on this. Contains: persisted state (completed/bookmarked/         ║
// ║  favourited/recents/history/tracker), their localStorage save      ║
// ║  functions, tree-traversal helpers (findNode, findPath, progress   ║
// ║  calculations), the search index, subject color-coding, and the    ║
// ║  esc() HTML-escaping helper used by every other module.            ║
// ╚══════════════════════════════════════════════════════════════════╝

// ╔══════════════════════════════════════════════════════════════════╗
// ║  ENGINE.JS — All logic: rendering, state, navigation, quizzes      ║
// ║                                                                    ║
// ║  This file changes RARELY. It contains every function that reads  ║
// ║  TREE_DATA / QUIZ_DATA (from data.js) and turns them into what     ║
// ║  you see on screen: the sidebar tree, search, bookmarks/          ║
// ║  favourites/recents/history/tracker, the timeline, the browse      ║
// ║  (cards/list/grid) view, the note renderer, and the full Practice ║
// ║  Hub (MCQs, flashcards, true/false, fill-blank, match-following).  ║
// ║                                                                    ║
// ║  Depends on data.js being loaded first (needs TREE_DATA/QUIZ_DATA ║
// ║  to already exist), and on the DOM elements defined in index.html.║
// ╚══════════════════════════════════════════════════════════════════╝

// ╔══════════════════════════════════════════════════════════╗
// ║  SUBJECT DASHBOARD META (icons/labels for home cards)     ║
// ╚══════════════════════════════════════════════════════════╝
const DASHBOARD_IDS = ["gs1", "gs2", "gs3", "gs4", "essay", "newspaper"];

// ╔══════════════════════════════════════════════════════════╗
// ║  STATE                                                    ║
// ╚══════════════════════════════════════════════════════════╝
// NOTE: `expanded` (which tree branches are open) is intentionally
// NOT persisted — every page refresh starts with the entire tree
// collapsed. `completed` (progress checkmarks) IS persisted, so
// your progress survives refreshes.
let expanded = {};
let selectedId = null;
let completed = {}; // { [leafId]: true }
let bookmarked = {}; // { [leafId]: true } — bookmarked notes
let favourited = {}; // { [leafId]: true } — favourite topics
let recents = []; // [{ id, title, ts }] — most recent first, max 20
let revisionHistory = []; // [{ id, title, ts, action }] — log of completed/reviewed/quiz events
let dailyTracker = {}; // { "YYYY-MM-DD": count } — topics touched per day
let quizResults = {}; // { [leafId]: { bestPct, lastPct, lastScore, total, attempts, ts } }

try {
  completed = JSON.parse(localStorage.getItem("upsc-completed") || "{}");
} catch (err) {
  completed = {};
}
try {
  bookmarked = JSON.parse(localStorage.getItem("upsc-bookmarked") || "{}");
} catch (err) {
  bookmarked = {};
}
try {
  favourited = JSON.parse(localStorage.getItem("upsc-favourited") || "{}");
} catch (err) {
  favourited = {};
}
try {
  recents = JSON.parse(localStorage.getItem("upsc-recents") || "[]");
} catch (err) {
  recents = [];
}
try {
  revisionHistory = JSON.parse(
    localStorage.getItem("upsc-revision-history") || "[]",
  );
} catch (err) {
  revisionHistory = [];
}
try {
  dailyTracker = JSON.parse(localStorage.getItem("upsc-daily-tracker") || "{}");
} catch (err) {
  dailyTracker = {};
}
try {
  quizResults = JSON.parse(localStorage.getItem("upsc-quiz-results") || "{}");
} catch (err) {
  quizResults = {};
}

function saveExpanded() {
  // Deliberately a no-op: expanded state is session-only (in-memory),
  // never written to localStorage, so refreshing always resets the tree.
}
function saveCompleted() {
  try {
    localStorage.setItem("upsc-completed", JSON.stringify(completed));
  } catch (err) { }
}
function saveBookmarked() {
  try {
    localStorage.setItem("upsc-bookmarked", JSON.stringify(bookmarked));
  } catch (err) { }
}
function saveFavourited() {
  try {
    localStorage.setItem("upsc-favourited", JSON.stringify(favourited));
  } catch (err) { }
}
function saveRecents() {
  try {
    localStorage.setItem("upsc-recents", JSON.stringify(recents));
  } catch (err) { }
}
function saveRevisionHistory() {
  try {
    localStorage.setItem(
      "upsc-revision-history",
      JSON.stringify(revisionHistory),
    );
  } catch (err) { }
}
function saveDailyTracker() {
  try {
    localStorage.setItem("upsc-daily-tracker", JSON.stringify(dailyTracker));
  } catch (err) { }
}
function saveQuizResults() {
  try {
    localStorage.setItem("upsc-quiz-results", JSON.stringify(quizResults));
  } catch (err) { }
}

// Record a completed quiz attempt (keeps best score + attempt count).
function recordQuizResult(nodeId, score, total) {
  const pct = total ? Math.round((score / total) * 100) : 0;
  const prev = quizResults[nodeId] || { bestPct: 0, attempts: 0 };
  quizResults[nodeId] = {
    bestPct: Math.max(prev.bestPct || 0, pct),
    lastPct: pct,
    lastScore: score,
    total,
    attempts: (prev.attempts || 0) + 1,
    ts: Date.now(),
  };
  saveQuizResults();
}

// Aggregate quiz stats for the dashboard.
function quizStats() {
  const ids = Object.keys(quizResults);
  const attempts = ids.reduce((s, id) => s + (quizResults[id].attempts || 0), 0);
  const avgBest = ids.length
    ? Math.round(
      ids.reduce((s, id) => s + (quizResults[id].bestPct || 0), 0) / ids.length,
    )
    : 0;
  return { quizzesTaken: ids.length, attempts, avgBest };
}

// Consecutive-day study streak (today may be empty and still count).
function studyStreak() {
  let streak = 0;
  const d = new Date();
  for (let i = 0; i < 400; i++) {
    const key =
      d.getFullYear() +
      "-" +
      String(d.getMonth() + 1).padStart(2, "0") +
      "-" +
      String(d.getDate()).padStart(2, "0");
    const e = dailyTracker[key];
    const has =
      e && ((e.count || 0) > 0 || (Array.isArray(e.opened) && e.opened.length));
    if (has) streak++;
    else if (i !== 0) break;
    d.setDate(d.getDate() - 1);
  }
  return streak;
}

// A small inline SVG progress ring/donut (no external libraries).
function svgRing(pct, color, size, stroke, label, sub) {
  const r = (size - stroke) / 2;
  const c = 2 * Math.PI * r;
  const off = c * (1 - Math.max(0, Math.min(100, pct)) / 100);
  const cx = size / 2;
  return `<svg class="ring" width="${size}" height="${size}" viewBox="0 0 ${size} ${size}">
    <circle cx="${cx}" cy="${cx}" r="${r}" fill="none" stroke="rgba(201,168,76,0.14)" stroke-width="${stroke}"/>
    <circle cx="${cx}" cy="${cx}" r="${r}" fill="none" stroke="${color}" stroke-width="${stroke}"
      stroke-linecap="round" stroke-dasharray="${c.toFixed(1)}" stroke-dashoffset="${off.toFixed(1)}"
      transform="rotate(-90 ${cx} ${cx})" style="transition:stroke-dashoffset 0.9s cubic-bezier(0.2,0.7,0.2,1)"/>
    <text x="50%" y="49%" text-anchor="middle" dominant-baseline="middle" class="ring-label">${esc(String(label))}</text>
    ${sub ? `<text x="50%" y="67%" text-anchor="middle" dominant-baseline="middle" class="ring-sub">${esc(String(sub))}</text>` : ""}
  </svg>`;
}

function todayKey() {
  const d = new Date();
  return (
    d.getFullYear() +
    "-" +
    String(d.getMonth() + 1).padStart(2, "0") +
    "-" +
    String(d.getDate()).padStart(2, "0")
  );
}

// Call whenever a note is opened — updates recents + daily tracker
function trackNoteOpen(node) {
  if (!node || !node.isLeaf) return;
  recents = recents.filter((r) => r.id !== node.id);
  recents.unshift({ id: node.id, title: node.title, ts: Date.now() });
  recents = recents.slice(0, 20);
  saveRecents();

  const key = todayKey();
  if (!dailyTracker[key]) dailyTracker[key] = { opened: [], count: 0 };
  if (!dailyTracker[key].opened.includes(node.id)) {
    dailyTracker[key].opened.push(node.id);
    dailyTracker[key].count = dailyTracker[key].opened.length;
    saveDailyTracker();
  }
}

// Call whenever a topic is marked done/reviewed or a quiz is completed
function logRevisionEvent(node, action) {
  if (!node) return;
  revisionHistory.unshift({
    id: node.id,
    title: node.title,
    ts: Date.now(),
    action,
  });
  revisionHistory = revisionHistory.slice(0, 200);
  saveRevisionHistory();
}

// ╔══════════════════════════════════════════════════════════╗
// ║  TREE HELPERS                                             ║
// ╚══════════════════════════════════════════════════════════╝
function findNode(nodes, id) {
  for (const n of nodes) {
    if (n.id === id) return n;
    if (n.children) {
      const f = findNode(n.children, id);
      if (f) return f;
    }
  }
  return null;
}

function findPath(nodes, id, path = []) {
  for (const n of nodes) {
    const newPath = [...path, n.title];
    if (n.id === id) return newPath;
    if (n.children) {
      const f = findPath(n.children, id, newPath);
      if (f) return f;
    }
  }
  return null;
}

// Collect all leaf ids (nodes with isLeaf:true) under a subtree, for progress calc
function collectLeaves(node) {
  let leaves = [];
  if (node.isLeaf && node.id !== "syllabus") leaves.push(node.id);
  if (node.children) {
    for (const c of node.children) leaves = leaves.concat(collectLeaves(c));
  }
  return leaves;
}

function subtreeProgress(node) {
  const leaves = collectLeaves(node);
  if (leaves.length === 0) return null;
  const done = leaves.filter((id) => completed[id]).length;
  return {
    done,
    total: leaves.length,
    pct: Math.round((done / leaves.length) * 100),
  };
}

// Returns the full chain of ancestor NODES (not just titles) from the
// root of TREE_DATA down to (and including) the node with the given id.
// Returns null if not found.
function findAncestorChain(nodes, id, chain = []) {
  for (const n of nodes) {
    const newChain = [...chain, n];
    if (n.id === id) return newChain;
    if (n.children) {
      const found = findAncestorChain(n.children, id, newChain);
      if (found) return found;
    }
  }
  return null;
}

// ╔══════════════════════════════════════════════════════════╗
// ║  CHAPTER-WISE PREV / NEXT NAVIGATION                       ║
// ║                                                              ║
// ║  A "chapter" is any node explicitly marked `isChapter: true` ║
// ║  in its data file (e.g. Chapter 1 combines Company Rule +    ║
// ║  Crown Rule under one isChapter node; Union Budget combines  ║
// ║  its 4 topics the same way). Prev/Next moves between the     ║
// ║  leaf topics flattened under the nearest such ancestor.       ║
// ║                                                              ║
// ║  When adding new content that should behave as its own       ║
// ║  navigable "chapter", set `isChapter: true` on that node.    ║
// ╚══════════════════════════════════════════════════════════╝

// Identify the "chapter" node for a given leaf id — the ancestor node
// explicitly marked `isChapter: true` (see e.g. ch1.js, budget/index.js).
// Falls back to the leaf's direct parent if no ancestor is marked, so
// navigation still works for content added before this flag existed.
function findChapterNode(leafId) {
  const chain = findAncestorChain(TREE_DATA, leafId);
  if (!chain) return null;
  for (let i = chain.length - 2; i >= 0; i--) {
    if (chain[i].isChapter) return chain[i];
  }
  return chain[chain.length - 2] || null; // fallback: direct parent
}

// Flatten a chapter node's descendant leaves, in tree order.
function chapterLeaves(chapterNode) {
  return collectLeaves(chapterNode)
    .map((id) => findNode(TREE_DATA, id))
    .filter(Boolean);
}

// Given a leaf id, return { chapterNode, leaves, index } describing its
// position within its chapter's flattened leaf list.
function getChapterPosition(leafId) {
  const chapterNode = findChapterNode(leafId);
  if (!chapterNode) return null;
  const leaves = chapterLeaves(chapterNode);
  const index = leaves.findIndex((n) => n.id === leafId);
  if (index === -1) return null;
  return { chapterNode, leaves, index };
}

// Find the chapter node that comes immediately after the given chapter
// node, among its own parent's children (skipping non-chapter siblings
// that have no leaves at all).
function findNextChapterNode(chapterNode) {
  const chain = findAncestorChain(TREE_DATA, chapterNode.id);
  if (!chain || chain.length < 2) return null;
  const parent = chain[chain.length - 2];
  const siblings = parent.children || [];
  const myIndex = siblings.findIndex((s) => s.id === chapterNode.id);
  for (let i = myIndex + 1; i < siblings.length; i++) {
    if (collectLeaves(siblings[i]).length > 0) return siblings[i];
  }
  return null;
}

// Mirror of findNextChapterNode looking backward: the chapter node that
// comes immediately BEFORE the given one among its parent's children
// (skipping empty siblings). Used so "Previous" at a chapter's first
// topic can step back into the prior chapter's last topic.
function findPrevChapterNode(chapterNode) {
  const chain = findAncestorChain(TREE_DATA, chapterNode.id);
  if (!chain || chain.length < 2) return null;
  const parent = chain[chain.length - 2];
  const siblings = parent.children || [];
  const myIndex = siblings.findIndex((s) => s.id === chapterNode.id);
  for (let i = myIndex - 1; i >= 0; i--) {
    if (collectLeaves(siblings[i]).length > 0) return siblings[i];
  }
  return null;
}

// Build the location header shown on a note from the node's position in
// the tree (rather than hand-written `subject`/`era`/`source` fields):
//   - crumb   : the full path as a breadcrumb, e.g.
//               "GS-2 › Laxmikanth › Part I › Chapter 1 › Company Rule"
//               (the top GS paper + every level in between, EXCLUDING the
//               subject node and the leaf topic itself)
//   - subject : the subject node's title (e.g. "Polity", "Geography") —
//               used on the source line in place of the old "Laxmikanth"
// Deriving these from the tree keeps every note's header correct and
// consistent automatically, no matter how many notes/chapters are added.
function buildNoteCrumb(nodeId) {
  const chain = findAncestorChain(TREE_DATA, nodeId);
  if (!chain || !chain.length) return { crumb: "", subject: "" };
  const top = chain[0];
  const hasSubject = chain.length > 2; // [paper, subject, ..., leaf]
  // Middle = everything between the subject and the leaf (both excluded).
  const middle = chain.slice(hasSubject ? 2 : 1, chain.length - 1);
  const crumbNodes = [top, ...middle];
  // The final segment (the topic's grouping, e.g. "Company Rule") also
  // shows its subtitle in parentheses when it has one, giving e.g.
  // "Company Rule (1773 – 1858)". Never applied to the GS paper itself.
  const crumb = crumbNodes
    .map((n, i) => {
      const isLast = i === crumbNodes.length - 1;
      return isLast && i > 0 && n.subtitle
        ? `${n.title} (${n.subtitle})`
        : n.title;
    })
    .join(" › ");
  const subject = hasSubject ? chain[1].title : top.title;
  return { crumb, subject };
}

function overallProgress() {
  let leaves = [];
  for (const n of TREE_DATA) leaves = leaves.concat(collectLeaves(n));
  const done = leaves.filter((id) => completed[id]).length;
  return {
    done,
    total: leaves.length,
    pct: leaves.length ? Math.round((done / leaves.length) * 100) : 0,
  };
}

// Flat index of all leaf nodes for search
function buildSearchIndex() {
  const index = [];
  function walk(nodes, pathTitles) {
    for (const n of nodes) {
      const newPath = [...pathTitles, n.title];
      if (n.isLeaf && n.id !== "syllabus") {
        index.push({ id: n.id, title: n.title, path: pathTitles.join(" › ") });
      }
      if (n.children) walk(n.children, newPath);
    }
  }
  walk(TREE_DATA, []);
  return index;
}
const SEARCH_INDEX = buildSearchIndex();

// ╔══════════════════════════════════════════════════════════╗
// ║  TREE RENDERING                                           ║
// ╚══════════════════════════════════════════════════════════╝
// ╔══════════════════════════════════════════════════════════╗
// ║  SUBJECT COLOR-CODING — distinct accent per top-level      ║
// ║  section, applied to tree rows (depth 0) and dash cards    ║
// ╚══════════════════════════════════════════════════════════╝
const SUBJECT_COLORS = {
  gs1: "#e0a458", // amber — History/Geography/Society/Culture
  gs2: "#C9A84C", // gold — Polity/IR (matches site's primary gold)
  gs3: "#5fb3a3", // teal-green — Economics/S&T/Environment
  gs4: "#c17bc4", // violet — Ethics/Integrity/Attitude
  essay: "#e8886b", // coral — Essay
  newspaper: "#6fa8dc", // blue — Daily Newspaper
  syllabus: "#9aa5b1", // neutral grey — reference/overview
};

function getSubjectColor(nodeId) {
  return SUBJECT_COLORS[nodeId] || "var(--gold)";
}

// esc() is used across every rendering module (tree, notes, practice hub)
// to safely HTML-escape user-visible text before inserting it via innerHTML.
function esc(str) {
  const div = document.createElement("div");
  div.textContent = str;
  return div.innerHTML;
}

// ── js/engine/loader.js ──
// ╔══════════════════════════════════════════════════════════════════╗
// ║  ENGINE-LOADER.JS — Lazy content loading (per-subject chunks)       ║
// ║                                                                    ║
// ║  Loaded SECOND (right after core.js). The bundle only ships a       ║
// ║  lightweight TREE_DATA "skeleton" — every node's structure          ║
// ║  (id/title/icon/hierarchy) but NOT its heavy `notes` body. The      ║
// ║  actual notes + quizzes live in files under js/content/ that        ║
// ║  MIRROR the js/data/ notes folder structure (e.g. js/content/       ║
// ║  gs2/polity/laxmikanth/part1/ch2/constituent-assembly-working.js).  ║
// ║  Each node's `chunk` field is that file's path (minus js/content/   ║
// ║  and .js); the file is fetched on demand the first time one of its  ║
// ║  topics is opened.                                                  ║
// ║                                                                    ║
// ║  Chunks are loaded by injecting a <script> tag (NOT fetch()) so     ║
// ║  the site keeps working when index.html is opened directly from     ║
// ║  disk (file://), where fetch/XHR are blocked by the browser.        ║
// ║                                                                    ║
// ║  Each chunk file is a single call:                                  ║
// ║     __registerContent("<mirror/path>", { notes:{...}, quizzes:{} });║
// ╚══════════════════════════════════════════════════════════════════╝

// leafId -> notes object (populated lazily as chunks load)
const NOTES_STORE = {};
// topicId -> quiz object (populated lazily as chunks load)
const QUIZ_DATA = {};

// chunkId -> true once its content file has loaded & registered
const __loadedChunks = {};
// chunkId -> [callbacks] waiting for that chunk to finish loading
const __loadingChunks = {};

// Called by each js/content/<chunk>.js file when it loads. Merges that
// subject's notes + quizzes into the in-memory stores and fires any
// callbacks that were waiting on this chunk.
function __registerContent(chunkId, payload) {
  if (payload && payload.notes) Object.assign(NOTES_STORE, payload.notes);
  if (payload && payload.quizzes) Object.assign(QUIZ_DATA, payload.quizzes);
  __loadedChunks[chunkId] = true;
  const waiting = __loadingChunks[chunkId] || [];
  delete __loadingChunks[chunkId];
  waiting.forEach((fn) => {
    try {
      fn();
    } catch (err) {
      /* ignore individual callback errors */
    }
  });
}

// Ensure a subject's content chunk is loaded, then run cb(). If the
// chunk is already loaded, cb() runs synchronously. Concurrent requests
// for the same chunk share a single <script> injection.
function ensureChunkLoaded(chunkId, cb) {
  if (!chunkId || __loadedChunks[chunkId]) {
    cb();
    return;
  }
  if (__loadingChunks[chunkId]) {
    __loadingChunks[chunkId].push(cb);
    return;
  }
  __loadingChunks[chunkId] = [cb];

  const script = document.createElement("script");
  // Path is relative to index.html (the document), NOT to bundle.js.
  script.src = "js/content/" + chunkId + ".js";
  script.async = false;
  script.onload = function () {
    // Normally __registerContent (called from inside the chunk) already
    // fired the callbacks. This is a safety net in case a chunk file
    // loaded but didn't register (e.g. empty/renamed) — don't hang.
    if (!__loadedChunks[chunkId]) {
      __loadedChunks[chunkId] = true;
      const waiting = __loadingChunks[chunkId] || [];
      delete __loadingChunks[chunkId];
      waiting.forEach((fn) => {
        try {
          fn();
        } catch (err) {}
      });
    }
  };
  script.onerror = function () {
    // Failed to load (missing file, offline). Fire callbacks anyway so
    // the note renderer can fall back to its "notes not added" state
    // instead of leaving the user on a permanent loading spinner.
    console.error("Failed to load content chunk:", chunkId);
    const waiting = __loadingChunks[chunkId] || [];
    delete __loadingChunks[chunkId];
    waiting.forEach((fn) => {
      try {
        fn();
      } catch (err) {}
    });
  };
  document.head.appendChild(script);
}

// Lightweight placeholder shown while a topic's content chunk loads.
// (In practice this flashes only on the very first open of each subject;
// once cached, subsequent opens render instantly.)
function renderNoteLoading(node) {
  const topbarTitle = document.getElementById("topbarTitle");
  if (topbarTitle) topbarTitle.textContent = node ? node.title : "Loading";
  const container = document.getElementById("notesContent");
  if (container) {
    container.innerHTML = `
      <div class="empty-state">
        <div class="empty-icon">⏳</div>
        <div class="empty-title">Loading…</div>
        <div class="empty-desc">Fetching notes for ${esc(node ? node.title : "this topic")}</div>
      </div>`;
  }
}

// ── js/engine/tree.js ──
// ╔══════════════════════════════════════════════════════════════════╗
// ║  ENGINE-TREE.JS — Sidebar: tree rendering & navigation views        ║
// ║                                                                    ║
// ║  Depends on engine-core.js (state, findNode, esc, colors).         ║
// ║  Contains: the nested tree renderer, sidebar nav tabs (Tree/       ║
// ║  Browse/Bookmarks/Favourites/Recent/History/Tracker/Timeline),     ║
// ║  and the list renderers for bookmarks/favourites/recents/history/  ║
// ║  tracker. Also the mobile drawer's tree-related handlers.          ║
// ╚══════════════════════════════════════════════════════════════════╝

function renderTree(nodes, depth, rootId) {
  let html = "";
  // Cap visual indent so deeply nested items (6-7 levels) never overflow
  // the sidebar — after depth 4, stop adding further indent.
  const cappedDepth = Math.min(depth, 4);
  const indentStep = 14;
  const rowPadding = 10 + cappedDepth * indentStep;

  for (const node of nodes) {
    const hasChildren = node.children && node.children.length > 0;
    const isExpanded = !!expanded[node.id];
    const isSelected = selectedId === node.id;
    const isLeaf = !!node.isLeaf && node.id !== "syllabus";
    const isDone = isLeaf && !!completed[node.id];
    const prog = !isLeaf ? subtreeProgress(node) : null;
    const currentRootId = depth === 0 ? node.id : rootId;
    const accentColor = getSubjectColor(currentRootId);

    html += `<div>`;
    html += `<div class="tree-row ${isSelected ? "selected" : ""}" data-id="${node.id}" data-haschildren="${hasChildren}" data-isleaf="${node.id === "syllabus" ? "special" : isLeaf}" style="padding-left:${rowPadding}px; ${isSelected ? `border-left-color:${accentColor};` : ""}">`;
    html += `<span class="tree-chevron ${hasChildren ? (isExpanded ? "expanded" : "") : "hidden"}" style="${depth === 0 ? `color:${accentColor};` : ""}">▶</span>`;
    if (isLeaf) {
      html += `<span class="tree-check ${isDone ? "done" : ""}" data-checkid="${node.id}" style="${isDone ? `background:${accentColor};border-color:${accentColor};` : ""}">${isDone ? "✓" : ""}</span>`;
    } else {
      html += `<span class="tree-icon">${node.icon || ""}</span>`;
    }
    html += `<div class="tree-label-wrap">`;
    html += `<div class="tree-title ${depth === 0 ? "depth-0" : ""}">${node.title}</div>`;
    if (node.subtitle)
      html += `<div class="tree-subtitle">${node.subtitle}</div>`;
    if (node.pageRef) html += `<div class="tree-pageref">${node.pageRef}</div>`;
    html += `</div>`;
    if (prog && prog.total > 0) {
      html += `<div class="tree-progress-mini">${prog.done}/${prog.total}</div>`;
    }
    html += `</div>`;

    if (hasChildren) {
      // Fixed small margin for the connector line only — does NOT compound
      // across nesting levels (each child renders its own indent via padding).
      html += `<div class="tree-children ${isExpanded ? "" : "collapsed"}" style="margin-left:14px">`;
      html += renderTree(node.children, depth + 1, currentRootId);
      html += `</div>`;
    }
    html += `</div>`;
  }
  return html;
}

function refreshTree() {
  if (sidebarView !== "tree") return; // don't overwrite an alternate view
  document.getElementById("treeContainer").innerHTML = renderTree(
    TREE_DATA,
    0,
    null,
  );
  attachTreeHandlers();
  refreshOverallProgress();
}

function refreshOverallProgress() {
  const p = overallProgress();
  document.getElementById("overallFill").style.width = p.pct + "%";
  document.getElementById("overallPct").textContent = p.pct + "%";
}

// ╔══════════════════════════════════════════════════════════╗
// ║  SIDEBAR VIEW SWITCHER — Tree / Bookmarks / Favourites /   ║
// ║  Recents / Revision History / Daily Tracker                ║
// ╚══════════════════════════════════════════════════════════╝
let sidebarView = "tree";

const SIDEBAR_VIEWS = [
  { id: "tree", label: "Tree", icon: "🌳" },
  { id: "browse", label: "Browse", icon: "🗂" },
  { id: "bookmarks", label: "Bookmarks", icon: "🔖" },
  { id: "favourites", label: "Favourites", icon: "⭐" },
  { id: "recents", label: "Recent", icon: "🕐" },
  { id: "history", label: "History", icon: "📋" },
  { id: "tracker", label: "Tracker", icon: "📅" },
  { id: "timeline", label: "Timeline", icon: "📈" },
];

function renderSidebarNav() {
  const nav = document.getElementById("sidebarNav");
  nav.innerHTML = SIDEBAR_VIEWS.map(
    (v) => `
    <button class="sidebar-nav-btn ${v.id === sidebarView ? "active" : ""}" data-view="${v.id}">${v.icon} ${v.label}</button>
  `,
  ).join("");
  nav.querySelectorAll(".sidebar-nav-btn").forEach((btn) => {
    btn.addEventListener("click", () => {
      sidebarView = btn.getAttribute("data-view");
      renderSidebarNav();
      switchSidebarView();
    });
  });
}

function switchSidebarView() {
  const container = document.getElementById("treeContainer");
  if (sidebarView === "tree") {
    refreshTree();
    return;
  }
  if (sidebarView === "bookmarks") {
    renderBookmarksList(container);
    return;
  }
  if (sidebarView === "favourites") {
    renderFavouritesList(container);
    return;
  }
  if (sidebarView === "recents") {
    renderRecentsList(container);
    return;
  }
  if (sidebarView === "history") {
    renderHistoryList(container);
    return;
  }
  if (sidebarView === "tracker") {
    renderTrackerView(container);
    return;
  }
  if (sidebarView === "timeline") {
    container.innerHTML = `<div class="side-list-empty">📈 Timeline opened in the main panel.<br>Tap any point on the timeline to view its notes.</div>`;
    selectedId = null;
    renderTimelineView();
    closeMobileDrawer();
    pushHistory();
    return;
  }
  if (sidebarView === "browse") {
    container.innerHTML = `<div class="side-list-empty">🗂 Browse view opened in the main panel.<br>Switch between Cards, List, and Grid layouts there.</div>`;
    selectedId = null;
    renderBrowseAllView();
    closeMobileDrawer();
    pushHistory();
    return;
  }
}

function openNoteFromSideList(id) {
  selectAndReveal(id);
  closeMobileDrawer();
}

function timeAgo(ts) {
  const diffMs = Date.now() - ts;
  const mins = Math.floor(diffMs / 60000);
  if (mins < 1) return "just now";
  if (mins < 60) return mins + "m ago";
  const hrs = Math.floor(mins / 60);
  if (hrs < 24) return hrs + "h ago";
  const days = Math.floor(hrs / 24);
  if (days < 30) return days + "d ago";
  return new Date(ts).toLocaleDateString();
}

function renderBookmarksList(container) {
  const ids = Object.keys(bookmarked).filter((id) => bookmarked[id]);
  if (ids.length === 0) {
    container.innerHTML = `<div class="side-list-empty">📑 No bookmarks yet.<br>Tap the bookmark icon on any note to save it here.</div>`;
    return;
  }
  container.innerHTML =
    `<div class="side-list">` +
    ids
      .map((id) => {
        const node = findNode(TREE_DATA, id);
        if (!node) return "";
        return `<div class="side-list-item" data-openid="${id}">
      <div class="side-list-title">🔖 ${esc(node.title)}</div>
      <div class="side-list-meta">${esc(findPath(TREE_DATA, id, []).slice(0, -1).join(" › ") || "")}</div>
    </div>`;
      })
      .join("") +
    `</div>`;
  attachSideListHandlers(container);
}

function renderFavouritesList(container) {
  const ids = Object.keys(favourited).filter((id) => favourited[id]);
  if (ids.length === 0) {
    container.innerHTML = `<div class="side-list-empty">⭐ No favourite topics yet.<br>Tap the star icon on any note to mark it as a favourite.</div>`;
    return;
  }
  container.innerHTML =
    `<div class="side-list">` +
    ids
      .map((id) => {
        const node = findNode(TREE_DATA, id);
        if (!node) return "";
        return `<div class="side-list-item" data-openid="${id}">
      <div class="side-list-title">⭐ ${esc(node.title)}</div>
      <div class="side-list-meta">${esc(findPath(TREE_DATA, id, []).slice(0, -1).join(" › ") || "")}</div>
    </div>`;
      })
      .join("") +
    `</div>`;
  attachSideListHandlers(container);
}

function renderRecentsList(container) {
  if (recents.length === 0) {
    container.innerHTML = `<div class="side-list-empty">🕐 Nothing opened yet.<br>Topics you view will show up here — pick up where you left off.</div>`;
    return;
  }
  container.innerHTML =
    `<div class="side-list">` +
    `<div class="side-list-item" data-openid="${recents[0].id}" style="background:rgba(201,168,76,0.08)">
      <div class="side-list-title">▶ Continue Reading: ${esc(recents[0].title)}</div>
      <div class="side-list-meta">${timeAgo(recents[0].ts)}</div>
    </div>` +
    recents
      .slice(1)
      .map(
        (r) => `
    <div class="side-list-item" data-openid="${r.id}">
      <div class="side-list-title">${esc(r.title)}</div>
      <div class="side-list-meta">${timeAgo(r.ts)}</div>
    </div>`,
      )
      .join("") +
    `</div>`;
  attachSideListHandlers(container);
}

function renderHistoryList(container) {
  if (revisionHistory.length === 0) {
    container.innerHTML = `<div class="side-list-empty">📋 No revision history yet.<br>Marking topics done or completing quizzes will log activity here.</div>`;
    return;
  }
  container.innerHTML =
    `<div class="side-list">` +
    revisionHistory
      .slice(0, 60)
      .map(
        (r) => `
    <div class="side-list-item" data-openid="${r.id}">
      <div class="side-list-title">${esc(r.title)}</div>
      <div class="side-list-meta">${esc(r.action)} &nbsp;·&nbsp; ${timeAgo(r.ts)}</div>
    </div>`,
      )
      .join("") +
    `</div>`;
  attachSideListHandlers(container);
}

function renderTrackerView(container) {
  const days = Object.keys(dailyTracker).sort().reverse().slice(0, 30);
  if (days.length === 0) {
    container.innerHTML = `<div class="side-list-empty">📅 No activity tracked yet.<br>Open any topic today to start your daily streak.</div>`;
    return;
  }
  const maxCount = Math.max(...days.map((d) => dailyTracker[d].count), 1);
  container.innerHTML =
    `<div class="tracker-cal">` +
    days
      .map((d) => {
        const info = dailyTracker[d];
        const pct = Math.round((info.count / maxCount) * 100);
        return `<div class="tracker-day-row" style="flex-direction:column;align-items:stretch">
      <div style="display:flex;justify-content:space-between">
        <span class="tracker-day-date">${esc(d)}</span>
        <span class="tracker-day-count">${info.count} topic${info.count !== 1 ? "s" : ""}</span>
      </div>
      <div class="tracker-bar-track"><div class="tracker-bar-fill" style="width:${pct}%"></div></div>
    </div>`;
      })
      .join("") +
    `</div>`;
}

function attachSideListHandlers(container) {
  container.querySelectorAll(".side-list-item").forEach((item) => {
    item.addEventListener("click", () => {
      openNoteFromSideList(item.getAttribute("data-openid"));
    });
  });
}

function attachTreeHandlers() {
  document.querySelectorAll(".tree-check").forEach((chk) => {
    chk.addEventListener("click", (e) => {
      e.stopPropagation();
      const id = chk.getAttribute("data-checkid");
      completed[id] = !completed[id];
      saveCompleted();
      refreshTree();
      if (selectedId === id) renderNotes(); // update mark-done button state if viewing this note
    });
  });

  document.querySelectorAll(".tree-row").forEach((row) => {
    row.addEventListener("click", () => {
      const id = row.getAttribute("data-id");
      const hasChildren = row.getAttribute("data-haschildren") === "true";
      const isLeafAttr = row.getAttribute("data-isleaf");

      if (hasChildren) {
        expanded[id] = !expanded[id];
        saveExpanded();
      }
      if (isLeafAttr === "true" || isLeafAttr === "special") {
        selectedId = selectedId === id ? null : id;
        renderNotes();
        closeMobileDrawer();
        pushHistory();
      }
      refreshTree();
    });
  });
}

// ╔══════════════════════════════════════════════════════════╗
// ║  SEARCH                                                   ║
// ╚══════════════════════════════════════════════════════════╝
const searchInput = document.getElementById("searchInput");
const searchResults = document.getElementById("searchResults");

searchInput.addEventListener("input", () => {
  const q = searchInput.value.trim().toLowerCase();
  if (!q) {
    searchResults.classList.remove("active");
    searchResults.innerHTML = "";
    return;
  }
  const matches = SEARCH_INDEX.filter(
    (item) =>
      item.title.toLowerCase().includes(q) ||
      item.path.toLowerCase().includes(q),
  ).slice(0, 15);
  if (matches.length === 0) {
    searchResults.innerHTML = `<div class="search-empty">No matching topics found</div>`;
  } else {
    searchResults.innerHTML = matches
      .map(
        (m) => `
      <div class="search-result-item" data-searchid="${m.id}">
        <div class="search-result-title">${m.title}</div>
        <div class="search-result-path">${m.path}</div>
      </div>`,
      )
      .join("");
  }
  searchResults.classList.add("active");

  document.querySelectorAll(".search-result-item").forEach((item) => {
    item.addEventListener("click", () => {
      const id = item.getAttribute("data-searchid");
      selectAndReveal(id);
      searchInput.value = "";
      searchResults.classList.remove("active");
      closeMobileDrawer();
    });
  });
});

document.addEventListener("click", (e) => {
  if (!e.target.closest(".search-wrap"))
    searchResults.classList.remove("active");
});

// Expand all ancestors of a node and select it
function selectAndReveal(id) {
  function expandAncestors(nodes, targetId, ancestors) {
    for (const n of nodes) {
      if (n.id === targetId) {
        ancestors.forEach((a) => (expanded[a] = true));
        return true;
      }
      if (
        n.children &&
        expandAncestors(n.children, targetId, [...ancestors, n.id])
      )
        return true;
    }
    return false;
  }
  expandAncestors(TREE_DATA, id, []);
  saveExpanded();
  selectedId = id;
  refreshTree();
  renderNotes();
  pushHistory();
  // On phones, close the drawer after opening a topic so the note is visible.
  if (
    window.matchMedia("(max-width: 680px)").matches &&
    sidebar.classList.contains("open")
  ) {
    closeMobileDrawer();
  }
}

// Smoothly scroll the sidebar tree so the given node's row is near the top
// of the tree container (used e.g. after clicking a dashboard card, so the
// revealed subject slides into view rather than being below the fold).
function scrollTreeToNode(id) {
  requestAnimationFrame(() => {
    const container = document.querySelector(".tree-container");
    if (!container) return;
    const row = container.querySelector(`.tree-row[data-id="${id}"]`);
    if (!row) return;
    const cRect = container.getBoundingClientRect();
    const rRect = row.getBoundingClientRect();
    const top = container.scrollTop + (rRect.top - cRect.top) - 8;
    container.scrollTo({ top: Math.max(0, top), behavior: "smooth" });
  });
}

